-- YGOResources JP NEURON. Paths recorded explicitly in artworks-index 433fe3d2223d3453b7732b5bad016196fb7b092f.
-- An artwork ID is scoped to one Konami CID. A local atlas variant has a separate identity.
CREATE TABLE neuron_artwork (
    cid text NOT NULL CHECK (cid ~ '^[1-9][0-9]{0,8}$'),
    artwork smallint NOT NULL CHECK (artwork > 0),
    image_path text NOT NULL CHECK (image_path ~ '^/[0-9]+/[0-9]+/[0-9]+_[0-9]+[.]png$'),
    PRIMARY KEY (cid,artwork)
);
ALTER TABLE deck_entry ADD COLUMN neuron_cid text, ADD COLUMN neuron_artwork smallint;
ALTER TABLE deck_entry ADD FOREIGN KEY (neuron_cid,neuron_artwork)
    REFERENCES neuron_artwork(cid,artwork) MATCH FULL;
ALTER TABLE deck_entry ADD CHECK (neuron_artwork IS NULL OR (game_code='YUGIOH' AND variant_id IS NULL));
DROP INDEX deck_entry_default_print;
CREATE UNIQUE INDEX deck_entry_default_print ON deck_entry(deck_id,section,card_id)
    WHERE variant_id IS NULL AND neuron_artwork IS NULL;
CREATE UNIQUE INDEX deck_entry_neuron_print ON deck_entry(deck_id,section,card_id,neuron_artwork)
    WHERE neuron_artwork IS NOT NULL;

